with valid as (select *, unit_price - quantity as line_total, round(quantity * 1.07, 2) as quantity_adjusted from order_items where order_id in (10, 36)) select case when quantity_adjusted >= 86 then 'PREMIUM' else 'STANDARD' end as quantity_adjusted_tier, order_id, percentile_approx(line_total, 0.95) as line_total_p95, stddev_samp(quantity) as quantity_stddev, approx_percentile(line_total, 0.95) as line_total_p95_2, dense_rank() over (partition by case when quantity_adjusted >= 86 then 'PREMIUM' else 'STANDARD' end order by percentile_approx(line_total, 0.95) desc) as line_total_p95_dense_rank from valid group by case when quantity_adjusted >= 86 then 'PREMIUM' else 'STANDARD' end, order_id having quantity_stddev < 0
